const PROFILES = [
  'Proveedor','Mesa de Partes','Área usuaria','Oficina de administración','DAI','Dependencia contrataciones','Planeamiento y Presupuesto','Unidad de Abastecimiento','Unidad de Contabilidad','Unidad de Tesorería'
];

