function executionUsesDeliverableRoute(type){return type!=='Bien'}
function handleExecutionAction(action,id){const c=CASES.find(x=>x.id===id&&x.module==='execution');if(!c)return;if(action==='au_evaluate_service'){openServiceEvaluation(c);return}if(action==='ua_verify_central'){openGoodsEvaluation(c,'central');return}if(action==='au_verify_remote'){openGoodsEvaluation(c,'remote');return}if(action==='provider_correct_service'){openExecutionCorrection(c);return}if(action==='provider_execute'){const next=executionUsesDeliverableRoute(c.type)?['mesa_receive_deliverable','Entregable presentado','Mesa de Partes','Entregable remitido a Mesa de Partes']:c.deliverySite==='Sede Central'?['ua_authorize_entry','Bien transportado al Almacén','Unidad de Abastecimiento','Bien presentado en Sede Central']:['au_authorize_remote','Bien transportado a sede desconcentrada','Área usuaria','Bien presentado en sede desconcentrada'];applyExecutionTransition(c,...next);return}
 const next={mesa_receive_deliverable:['mesa_forward_deliverable','Entregable recepcionado','Mesa de Partes','Entregable recepcionado por Mesa de Partes'],mesa_forward_deliverable:['au_evaluate_service','Entregable pendiente de evaluación','Área usuaria','Entregable derivado al Área usuaria'],ua_notify_service:['provider_correct_service','Observaciones notificadas al proveedor','Proveedor','Observaciones notificadas'],ua_authorize_entry:['ua_request_accompaniment','Ingreso físico autorizado','Unidad de Abastecimiento','Ingreso al Almacén autorizado'],ua_request_accompaniment:['au_designate_verifier','Acompañamiento solicitado','Área usuaria','Acompañamiento solicitado al Área usuaria'],au_designate_verifier:['ua_verify_central','Responsable designado','Unidad de Abastecimiento','Responsable de verificación designado'],ua_receive_goods:['ua_deliver_goods','Bien recepcionado en Almacén','Unidad de Abastecimiento','Bien recepcionado y PECOSA preparada'],ua_deliver_goods:['au_receive_central','Bien entregado al Área usuaria','Área usuaria','Bien entregado desde Almacén'],au_authorize_remote:['au_verify_remote','Ingreso físico autorizado en sede','Área usuaria','Ingreso autorizado en sede desconcentrada'],provider_remove_goods:['completed','Bien retirado · ejecución cerrada con incumplimiento','Proveedor','Bien observado retirado'],au_issue_conformity:['completed','Conformidad emitida · ejecución finalizada','Área usuaria','Acta de Conformidad emitida'],au_receive_central:['completed','Bien recepcionado · ejecución finalizada','Área usuaria','Bien recepcionado por el Área usuaria'],au_receive_remote:['completed','Guía firmada · ejecución finalizada','Área usuaria','Bien y Guía de Remisión recepcionados']}[action];if(next){applyExecutionTransition(c,...next);if(['au_issue_conformity','au_receive_central','au_receive_remote'].includes(action))createPaymentFromExecution(c)}}
function applyExecutionTransition(c,stage,label,owner,event){c.execStage=stage;c.state=label;c.owner=owner;c.status=stage==='completed'?'success':stage.includes('correct')||stage.includes('remove')?'warning':'info';c.progress=executionProgress(stage);c.execHistory=c.execHistory||[];c.execHistory.push({title:event,detail:`${state.profile} · ${new Date().toLocaleString('es-PE')}`});render();showToast(`${c.id}: ${event}.`)}
function executionProgress(s){return {provider_execute:8,mesa_receive_deliverable:18,mesa_forward_deliverable:24,au_evaluate_service:32,ua_notify_service:38,provider_correct_service:44,au_issue_conformity:82,ua_authorize_entry:30,ua_request_accompaniment:38,au_designate_verifier:45,ua_verify_central:54,ua_receive_goods:65,ua_deliver_goods:74,au_receive_central:88,au_authorize_remote:34,au_verify_remote:52,au_receive_remote:82,provider_remove_goods:75,completed:100}[s]||25}
