function renderAudit(){return `${pageHead('Auditoría','Registro inalterable simulado de accesos, decisiones, firmas y cambios de estado.',`<button class="btn btn--outline" data-export="excel">Exportar bitácora</button>`)}<section class="card"><div class="toolbar"><div class="filters"><input class="filter-control" value="02/08/2026" aria-label="Fecha"><select class="filter-control"><option>Todos los eventos</option><option>Acceso</option><option>Firma</option><option>Cambio de estado</option></select></div></div><div class="activity-list">${activity('◎','Inicio de sesión SSO',`María Torres · ${state.profile} · IP 10.12.8.24`,'08:41')}${activity('✓','Firma digital simulada','Anexo N.° 11 · EXP-2026-00131 · SHA-256: 98f…a21','09:03')}${activity('↗','Cambio de estado','En revisión → Devengado aprobado · EXP-2026-00131','09:11')}${activity('▤','Documento incorporado','Informe técnico v2 · EXP-2026-00127','09:24')}${activity('!','Observación registrada','Falta firma del titular · EXP-2026-00142','09:37')}</div><p class="audit-line"><b>Nota:</b> este prototipo no persiste datos. La bitácora ilustra la información mínima recomendada para auditoría.</p></section>`}

function handleAction(action){
 const newModule={'new-cmn':'cmn','new-requirement':'requirement','new-payment':'payment','new-execution':'execution','new-modification':'modification','new-resolution':'resolution'}[action];
 if(newModule){if(newModule==='cmn')openCmnAnexo3Form();else if(newModule==='requirement')openRequirementForm();else if(newModule==='payment')openPaymentForm();else if(newModule==='execution')openExecutionForm();else if(newModule==='modification')openModificationForm();else if(newModule==='resolution')openResolutionForm();else openRecordForm(newModule);return}
 const templates={
  conformity:['Acta de Conformidad · Anexo N.° 11',[['Orden o contrato','text','OS-000172'],['Prestación','text','Consultoría para expediente técnico'],['¿Existen observaciones?','select','No|Sí'],['Días de retraso','number','0'],['Otras penalidades','text','No corresponde']]],
  penalty:['Determinación de penalidades · Anexo N.° 10',[['Monto vigente','number','48500'],['Plazo del entregable (días)','number','30'],['Días de atraso','number','2'],['Penalidad calculada','text','S/ 646.67 (simulado)']]],
  extension:['Evaluar ampliación de plazo',[['Fecha fin del hecho generador','date',''],['Fecha de solicitud','date',''],['Días solicitados','number',''],['Sustento técnico','textarea',''],['Resultado','select','Procedente|Improcedente']]]
 };
 const fallback=['Registrar actuación',[['Expediente','text','EXP-2026-'],['Comentario','textarea','Detalle la actuación o adjunte el documento correspondiente']]];
 openForm(...(templates[action]||fallback));
}

const RECORD_FORMS = {
 cmn:{title:'Registro de Gestión CM',types:['Bien','Servicio','Consultoría','Locación'],states:['Solicitud Anexo 3','En revisión','Subsanación requerida','Aprobación Anexo 4','Notificado'],extra:'Tipo de modificación',extraOptions:['Inclusión ordinaria','Inclusión extraordinaria','Exclusión']},
 requirement:{title:'Registro de Requerimiento a Notificación',types:['Bien','Servicio','Consultoría','Locación'],states:['En elaboración','En autorización','En revisión','Subsanación requerida','Indagación de mercado','CCP pendiente','Perfeccionamiento','Notificado'],extra:'Documento técnico',extraOptions:['EETT - Anexo 1','TDR - Anexo 2','TDR persona natural - Anexo 3','TDR consultoría - Anexo 4']},
 payment:{title:'Registro de Pago',types:['Bien','Servicio','Consultoría','Locación'],states:['Conformidad recibida','Control de pagos','Control previo','Observado','Devengado aprobado','Giro registrado'],extra:'Número de pago',extraOptions:['Pago único','Pago N.° 1','Pago N.° 2','Pago final']},
 execution:{title:'Registro de Ejecución Contractual',types:['Bien','Servicio','Consultoría','Locación'],states:['Ejecución iniciada','Entregable recibido','Evaluación de entregable','Con observaciones','Subsanado','Conformidad emitida'],extra:'Resultado de recepción',extraOptions:['Pendiente de evaluación','Conforme','Con observaciones','Bien retirado']},
 modification:{title:'Registro de Modificación o Ampliación',types:['Modificación contractual','Ampliación de plazo'],states:['Solicitud recibida','En derivación','Evaluación de ampliación','Opinión técnica','Aprobada','Denegada','Notificada'],extra:'Condición de la solicitud',extraOptions:['Dentro del plazo','Fuera del plazo','Sustento completo','Requiere opinión técnica']},
 resolution:{title:'Registro de Resolución Contractual',types:['Total','Parcial'],states:['Solicitud recibida','Informe de causal','En apercibimiento','Opinión técnica','Carta en elaboración','Resuelto','Denegado'],extra:'Causal',extraOptions:['Acumulación máxima de penalidad','Hecho sobresaliente','Incumplimiento','Mutuo acuerdo','Resolución unilateral']}
};

function openRecordForm(module,record=null){
 const cfg=RECORD_FORMS[module];if(!cfg)return;
 if(module==='resolution'&&!resolutionAllowed().length){showToast('Tu perfil no tiene acceso a Resolución');return}
 if(module!=='resolution'&&!allowed(module)){showToast('Tu perfil no tiene acceso a este módulo');return}
 const isEdit=Boolean(record);const rawAmount=record?String(record.amount).replace(/[^0-9.]/g,''):'';
 $('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">${isEdit?'Modificar registro':'Nuevo registro temporal'}</span><h2>${cfg.title}</h2><p>${isEdit?`Editando ${record.id}`:'El registro aparecerá inmediatamente en las tablas del prototipo.'}</p></div><div class="case-detail-body"><form id="recordForm" class="form-grid">
   <div class="form-field form-field--full"><label>Denominación de la contratación</label><input name="title" required value="${escapeHtml(record?.title||'')}"></div>
   <div class="form-field"><label>Tipo</label><select name="type">${cfg.types.map(x=>`<option ${record?.type===x?'selected':''}>${x}</option>`).join('')}</select></div>
   <div class="form-field"><label>Estado</label><select name="state">${cfg.states.map(x=>`<option ${record?.state===x?'selected':''}>${x}</option>`).join('')}</select></div>
   <div class="form-field"><label>Área responsable</label><input name="owner" required value="${escapeHtml(record?.owner||state.profile)}"></div>
   <div class="form-field"><label>Monto (S/)</label><input name="amount" type="number" min="0" step="0.01" required value="${rawAmount}"></div>
   <div class="form-field"><label>Orden o contrato</label><input name="order" required value="${escapeHtml(record?.order||'OS-')}"></div>
   <div class="form-field"><label>RUC del proveedor</label><input name="ruc" inputmode="numeric" maxlength="11" pattern="[0-9]{11}" required value="${escapeHtml(record?.ruc||'')}"></div>
   <div class="form-field"><label>Plazo / vencimiento</label><input name="due" required value="${escapeHtml(record?.due||'5 días')}"></div>
   <div class="form-field"><label>${cfg.extra}</label><select name="detail">${cfg.extraOptions.map(x=>`<option ${record?.detail===x?'selected':''}>${x}</option>`).join('')}</select></div>
   <div class="form-field form-field--full"><label>Descripción o sustento</label><textarea name="description" placeholder="Detalle la actuación y su sustento">${escapeHtml(record?.description||'')}</textarea></div>
   <div class="form-field form-field--full"><label>Documentos de sustento</label><input type="file" multiple></div>
   <div class="form-actions"><button type="button" class="btn btn--outline" data-close-record>Cancelar</button><button type="submit" class="btn btn--primary">${isEdit?'Guardar cambios':'Registrar'}</button></div>
 </form></div>`;
 $('[data-close-record]').addEventListener('click',()=>$('#caseDialog').close());
 $('#recordForm').addEventListener('submit',e=>{e.preventDefault();saveRecord(module,record?.id,new FormData(e.currentTarget))});$('#caseDialog').showModal();
}

function saveRecord(module,id,data){
 const amount=Number(data.get('amount')||0);const selectedState=String(data.get('state'));
 const values={title:String(data.get('title')).trim(),type:String(data.get('type')),module,state:selectedState,status:statusFor(selectedState),owner:String(data.get('owner')).trim(),amount:formatMoney(amount),due:String(data.get('due')).trim(),ruc:String(data.get('ruc')).trim(),order:String(data.get('order')).trim(),detail:String(data.get('detail')),description:String(data.get('description')||'').trim()};
 if(id){const record=CASES.find(c=>c.id===id);if(module==='cmn'){delete values.state;delete values.status;delete values.owner}Object.assign(record,values);showToast(`${id} actualizado correctamente.`)}
 else{const workflow=module==='cmn'?{cmnStage:'draft_anexo3',state:'Borrador de Anexo 3',status:'info',owner:'Área usuaria',progress:10,cmnHistory:[{title:'Solicitud CMN registrada',detail:`Área usuaria · ${new Date().toLocaleString('es-PE')}`}]}:{};const newRecord={id:`EXP-2026-${String(nextCaseNumber++).padStart(5,'0')}`,progress:12,...values,...workflow};CASES.unshift(newRecord);showToast(`${newRecord.id} registrado temporalmente.`)}
 $('#caseDialog').close();render();
}
function editRecord(id){const record=CASES.find(c=>c.id===id);if(!record||!caseVisible(record)){showToast('Tu perfil no puede modificar este registro');return}if(record.module==='cmn'){if(state.profile!=='Área usuaria'||record.cmnStage!=='anexo3_draft'){showToast('El Anexo 3 sólo puede editarse por el Área usuaria mientras está en borrador');return}openCmnAnexo3Form(record);return}if(record.module==='requirement'){if(state.profile!=='Área usuaria'||record.reqStage!=='draft'){showToast('El requerimiento sólo puede editarse por el Área usuaria mientras está en borrador');return}openRequirementForm(record);return}openRecordForm(record.module,record)}
function deleteRecord(id){
 const index=CASES.findIndex(c=>c.id===id);if(index<0||!caseVisible(CASES[index])){showToast('Tu perfil no puede eliminar este registro');return}
 if(CASES[index].module==='cmn'&&(state.profile!=='Área usuaria'||CASES[index].cmnStage!=='anexo3_draft')){showToast('Sólo el Área usuaria puede eliminar un borrador del Anexo 3');return}
 if(CASES[index].module==='requirement'&&(state.profile!=='Área usuaria'||CASES[index].reqStage!=='draft')){showToast('Sólo el Área usuaria puede eliminar un requerimiento en borrador');return}
 if(!window.confirm(`¿Eliminar temporalmente el registro ${id}?`))return;
 CASES.splice(index,1);render();showToast(`${id} eliminado del prototipo.`)
}
function statusFor(value){const v=value.toLowerCase();if(v.includes('observ')||v.includes('apercib')||v.includes('deneg'))return v.includes('deneg')?'danger':'warning';if(v.includes('aprob')||v.includes('conform')||v.includes('giro')||v.includes('resuelto')||v.includes('notificado'))return 'success';return 'info'}
function formatMoney(value){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(value).replace('PEN','S/')}
function escapeHtml(value){return String(value).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}

function openForm(title,fields){
 $('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Formulario simulado</span><h2>${title}</h2><p>Los campos reflejan los documentos y decisiones principales del flujo.</p></div><div class="case-detail-body"><form id="demoForm" class="form-grid">${fields.map(([label,type,value])=>formField(label,type,value)).join('')}<div class="form-field form-field--full"><label>Documentos de sustento</label><input type="file" multiple></div><div class="form-actions"><button type="button" class="btn btn--outline" data-toast="Borrador guardado localmente (simulación).">Guardar borrador</button><button type="submit" class="btn btn--primary">Registrar y continuar</button></div></form></div>`;
 $('#demoForm').addEventListener('submit',e=>{e.preventDefault();$('#caseDialog').close();showToast('Registro enviado. Se generó la trazabilidad simulada.')});$('#caseDialog').showModal();
}
function formField(label,type,value){
 if(type==='textarea')return `<div class="form-field form-field--full"><label>${label}</label><textarea placeholder="${value||''}"></textarea></div>`;
 if(type==='select')return `<div class="form-field"><label>${label}</label><select>${value.split('|').map(x=>`<option>${x}</option>`).join('')}</select></div>`;
 return `<div class="form-field"><label>${label}</label><input type="${type}" value="${value||''}"></div>`
}

function openCase(id){
 const c=CASES.find(x=>x.id===id);if(!c||!caseVisible(c)){showToast('Tu perfil no tiene acceso a este expediente');return}
 const processHistory=c.module==='cmn'?c.cmnHistory:c.module==='requirement'?c.reqHistory:c.module==='payment'?c.payHistory:c.module==='execution'?c.execHistory:c.module==='modification'?c.modHistory:c.module==='resolution'?c.resHistory:null;
 const history=processHistory?(processHistory||[]).map(h=>timeline(h.title,h.detail,'done')).join(''):`${timeline('Expediente registrado','Mesa de Partes · 29/07/2026 09:12','done')}${timeline('Revisión documental completada','Unidad de Abastecimiento · 30/07/2026 16:40','done')}`;
 const finished=c.cmnStage==='completed'||c.reqStage==='completed'||c.payStage==='completed'||c.execStage==='completed'||c.modStage==='completed'||c.resStage==='completed';const current=finished?'':timeline(c.state,`${c.owner} · plazo ${c.due}`,'active');
 const action=c.module==='cmn'?cmnActionButtons(c):c.module==='requirement'?requirementActionButtons(c):c.module==='payment'?paymentActionButtons(c):c.module==='execution'?executionActionButtons(c):c.module==='modification'?modificationActionButtons(c):c.module==='resolution'?resolutionActionButtons(c):'<button class="btn btn--primary" data-action="review">Atender actuación</button>';
 const lastObservation=c.cmnObservation||c.reqObservation||c.payObservation||c.uaDocumentObservation||c.accountingObservation||c.execObservation||c.goodsObservation||c.modObservation||c.extensionDenialReason||c.extensionEvaluation||c.technicalOpinion||c.resObservation;
 $('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Expediente digital</span><h2>${c.id}</h2><p>${c.title}</p></div><div class="case-detail-body"><div class="case-summary">${c.module==='resolution'?summary('Tipo de resolución',c.resolutionType):''}${summary('Estado',c.state)}${summary('Orden / contrato',c.order)}${summary('Monto',c.amount)}${summary('RUC',c.ruc)}</div><h3>Historial del proceso</h3><div class="timeline">${history}${current}</div>${lastObservation?`<div class="sso-note"><span>!</span><p><b>Última observación</b><br>${escapeHtml(lastObservation)}</p></div>`:''}<div class="form-actions"><button class="btn btn--outline" data-export="pdf">Ficha PDF</button>${action}</div></div>`;$('#caseDialog').showModal();
}
function summary(k,v){return `<div class="summary-item"><small>${k}</small><b>${v}</b></div>`}
function timeline(t,s,cl){return `<div class="timeline-item ${cl}"><span class="timeline-dot">${cl==='done'?'✓':cl==='active'?'!':''}</span><span class="timeline-content"><b>${t}</b><small>${s}</small></span></div>`}

function exportReport(type){
 if(type==='excel'){
  const rows=[['Expediente','Contratación','Estado','Monto'],...visibleCases().map(c=>[c.id,c.title,c.state,c.amount])];
  const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(';')).join('\n');
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='SIGCM_reporte_2026.csv';a.click();URL.revokeObjectURL(a.href);showToast('Reporte compatible con Excel generado.');
 }else{showToast('Se abrió la vista de impresión. Elige “Guardar como PDF”.');setTimeout(()=>window.print(),350)}
}
let toastTimer;function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
init();
